BEGIN;

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM organizations WHERE code NOT LIKE 'SEED-%') THEN
    RAISE EXCEPTION 'Refusing to load sample data: this database already holds real organizations.';
  END IF;
END $$;

-- Organization structure

-- Staff accounts (no passwords: they cannot sign in) and their roles and offices



-- Programs, projects and budgets

-- People, applications, fees and volunteers
UPDATE users SET "personId" = '5eed0009-0000-4000-8000-000000000001' WHERE id = '5eed000a-0000-4000-8000-000000000007' AND "personId" IS NULL;

  ON CONFLICT (year) DO UPDATE SET "lastNumber" = GREATEST(volunteer_number_counters."lastNumber", 6), "updatedAt" = now();

-- Assignments (volunteers 1-4 in Addis Ababa, 5-6 in Adama)

-- Attendance for the last five days (all in existing monthly partitions).
-- Yesterday is still waiting for the supervisor; older days are verified.
SELECT md5('seed-att-' || a.id::text || d::date::text)::uuid,
       d::date, a.id, '08:30', '16:30',
       9.0050 + (extract(day FROM d)::int % 5) * 0.0001,
       38.7630 + (extract(day FROM d)::int % 5) * 0.0001,
       (CASE WHEN extract(day FROM d)::int % 6 = 0 THEN 'LATE' ELSE 'PRESENT' END)::"AttendanceStatus",
       (CASE WHEN d::date = current_date - 1 THEN 'PENDING' ELSE 'VERIFIED' END)::"VerificationStatus",
       CASE WHEN d::date = current_date - 1 THEN NULL ELSE '5eed000a-0000-4000-8000-000000000004'::uuid END,
       CASE WHEN d::date = current_date - 1 THEN NULL ELSE now() END
FROM volunteer_assignments a
CROSS JOIN generate_series(current_date - 5, current_date - 1, interval '1 day') AS d
WHERE a.id IN ('5eed000d-0000-4000-8000-000000000001', '5eed000d-0000-4000-8000-000000000002', '5eed000d-0000-4000-8000-000000000003', '5eed000d-0000-4000-8000-000000000004', '5eed000d-0000-4000-8000-000000000005', '5eed000d-0000-4000-8000-000000000006')
ON CONFLICT DO NOTHING;

-- Allowance requests at every stage of the lifecycle, and two payouts

COMMIT;

SELECT 'sample data loaded' AS result,
  (SELECT count(*) FROM volunteers) AS volunteers,
  (SELECT count(*) FROM volunteer_attendance) AS attendance_rows,
  (SELECT count(*) FROM allowance_requests) AS allowance_requests,
  (SELECT count(*) FROM user_roles WHERE "revokedAt" IS NULL) AS staff_roles;
